export function removerEspacos(texto) {
  return texto.trim();
}

export function tornarMaiusculo(texto) {
  return texto.toUpperCase();
}

export function removerPontuacao(texto) {
  return texto.replace(/[.,!?;:]/g, '');
}

export function criarSubstituidor(de, para) {
  return function (texto) {
    return texto.split(de).join(para);
  };
}

