import { removerEspacos } from './transformacoes.mjs';

export function criarPipeline(...transformacoes) {
  return function (texto) {
    let atual = texto;
    for (const transformacao of transformacoes) {
      atual = transformacao(atual);
    }
    return atual;
  };
}

export function aplicarPipeline(texto, ...transformacoes) {
  const pipeline = criarPipeline(removerEspacos, ...transformacoes);
  return pipeline(texto);
}

