import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  removerEspacos,
  tornarMaiusculo,
  removerPontuacao,
  criarSubstituidor,
} from './lib/transformacoes.mjs';
import { criarPipeline, aplicarPipeline } from './lib/pipeline.mjs';

test('transformações básicas funcionam sozinhas', () => {
  assert.equal(removerEspacos('  olá mundo  '), 'olá mundo');
  assert.equal(tornarMaiusculo('abc'), 'ABC');
});

test('removerPontuacao tira os sinais do texto', () => {
  assert.equal(removerPontuacao('Olá, mundo!'), 'Olá mundo');
  assert.equal(removerPontuacao('Sim; claro: tudo.'), 'Sim claro tudo');
});

test('criarSubstituidor devolve closures independentes', () => {
  const trocarAporO = criarSubstituidor('a', 'o');
  const trocarEporI = criarSubstituidor('e', 'i');
  assert.equal(trocarAporO('banana'), 'bonono');
  assert.equal(trocarEporI('bebida'), 'bibida');
});

test('criarPipeline compõe transformações na ordem', () => {
  const limpar = criarPipeline(removerEspacos, tornarMaiusculo);
  assert.equal(limpar('  oi  '), 'OI');
  assert.equal(criarPipeline()('texto'), 'texto');
});

test('aplicarPipeline limpa os cantos e aplica as transformações', () => {
  assert.equal(
    aplicarPipeline('  olá, mundo!  ', removerPontuacao, tornarMaiusculo),
    'OLÁ MUNDO',
  );
});
